var N=['Extreme wide','Wide','Medium','Medium close-up','Close-up','Extreme close-up'],Z=[.28,.5,1,1.7,3,6],Q=['Place and scale: the person is small against the world.','Whole body and surroundings.','Waist up: the workhorse of conversation.','Chest up: closer, more personal.','The face fills the frame: emotion.','A single detail, such as the eyes: intensity.'];
