D.cuts=function(){root.innerHTML='<div class="dm"><div class="vf"><div class="ly fa" id="fa"><i class="dot" id="da"></i></div><div class="ly fb" id="fb"><i class="dot" id="db"></i></div><div class="ly flash" id="fh"></div>'+tag('Pick a cut')+'</div><div class="ctl" id="ct"></div><p id="md">Choose a transition to see how the same two shots feel when joined differently.</p></div>';
var fa=$('#fa'),fb=$('#fb'),da=$('#da'),db=$('#db'),fh=$('#fh');var R=function(){g.killTweensOf([fa,fb,da,db,fh]);g.set(fb,{opacity:0,clipPath:'none'});g.set(fa,{scale:1});g.set([da,db],{scale:1,xPercent:-50,yPercent:-50});g.set(fh,{opacity:0})};R();
var M={'Hard cut':[function(){g.timeline().to({},{duration:.8}).set(fb,{opacity:1})},'An instant switch: the default grammar of film, invisible when it works.'],'Crossfade':[function(){g.to(fb,{opacity:1,duration:1.3})},'One image melts into the next, suggesting time passing or a thought drifting.'],'Wipe':[function(){g.fromTo(fb,{opacity:1,clipPath:'inset(0 100% 0 0)'},{clipPath:'inset(0 0% 0 0)',duration:1,ease:'power2.inOut'})},'A line sweeps across and replaces the frame: playful, stylised, often period.'],'Iris':[function(){g.fromTo(fb,{opacity:1,clipPath:'circle(0% at 50% 50%)'},{clipPath:'circle(75% at 50% 50%)',duration:1.1,ease:'power2.inOut'})},'A circle opens on the picture, a silent-era classic.'],'Match cut':[function(){g.timeline().to(da,{scale:1.25,duration:.8,ease:'power2.in'}).set(fb,{opacity:1}).fromTo(db,{scale:1.25},{scale:1,duration:.8,ease:'power2.out'})},'Two different shots share a shape, so the cut connects ideas, as in the bone-to-satellite cut of 2001.'],'Smash cut':[function(){g.timeline().to(fa,{scale:1.12,duration:.5,ease:'power3.in'}).set(fb,{opacity:1}).fromTo(fh,{opacity:1},{opacity:0,duration:.5})},'A sudden jump from calm to chaos or back, for shock or comedy.']};
pills(M,function(k,f){R();f()})};
